From fda3ab6457f1a23439ca8cd879e5ff9c7deab2bf Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:02:32 +0100
Subject: [PATCH] plasmaquick/configmodel: add preferredWidth and
 preferredHeight

Every widget's settings window opened at the same default size, which
is far too big for widgets with a few options. A widget's config model
can now suggest the size its settings window opens with the first time.

BUG: 488318
---
 src/plasmaquick/configmodel.cpp | 29 +++++++++++++++++++++++
 src/plasmaquick/configmodel.h   | 41 +++++++++++++++++++++++++++++++++
 2 files changed, 70 insertions(+)

diff --git a/src/plasmaquick/configmodel.cpp b/src/plasmaquick/configmodel.cpp
index f128e464c..560b3bd07 100644
--- a/src/plasmaquick/configmodel.cpp
+++ b/src/plasmaquick/configmodel.cpp
@@ -26,6 +26,8 @@ public:
     ConfigModel *q;
     QList<ConfigCategory *> categories;
     QPointer<Plasma::Applet> appletInterface;
+    qreal preferredWidth = 0;
+    qreal preferredHeight = 0;

     void appendCategory(ConfigCategory *c);
     void removeCategory(ConfigCategory *c);
@@ -306,6 +308,33 @@ QQmlListProperty<ConfigCategory> ConfigModel::categories()
                                             ConfigModelPrivate::categories_clear);
 }

+qreal ConfigModel::preferredWidth() const
+{
+    return d->preferredWidth;
+}
+
+void ConfigModel::setPreferredWidth(qreal width)
+{
+    if (qFuzzyCompare(d->preferredWidth, width)) {
+        return;
+    }
+    d->preferredWidth = width;
+    Q_EMIT preferredWidthChanged();
+}
+
+qreal ConfigModel::preferredHeight() const
+{
+    return d->preferredHeight;
+}
+
+void ConfigModel::setPreferredHeight(qreal height)
+{
+    if (qFuzzyCompare(d->preferredHeight, height)) {
+        return;
+    }
+    d->preferredHeight = height;
+    Q_EMIT preferredHeightChanged();
+}
 }

 #include "moc_configmodel.cpp"
diff --git a/src/plasmaquick/configmodel.h b/src/plasmaquick/configmodel.h
index 66eda933f..2060313d2 100644
--- a/src/plasmaquick/configmodel.h
+++ b/src/plasmaquick/configmodel.h
@@ -58,6 +58,26 @@ class ConfigCategory;
  * \qmlproperty int ConfigModel::count
  */

+/*!
+ * \qmlproperty real ConfigModel::preferredWidth
+ *
+ * The width the configuration dialog should open with the first time,
+ * or 0 to use the default size. The user's own size is remembered and
+ * takes precedence.
+ *
+ * \since 6.9
+ */
+
+/*!
+ * \qmlproperty real ConfigModel::preferredHeight
+ *
+ * The height the configuration dialog should open with the first time,
+ * or 0 to use the default size. The user's own size is remembered and
+ * takes precedence.
+ *
+ * \since 6.9
+ */
+
 /*!
  * \qmlmethod void ConfigModel::appendCategory(string iconName, string name, string path, string pluginName, bool visible)
  */
@@ -105,6 +125,18 @@ class PLASMAQUICK_EXPORT ConfigModel : public QAbstractListModel
      */
     Q_PROPERTY(int count READ count NOTIFY countChanged)

+    /*!
+     * \property PlasmaQuick::ConfigModel::preferredWidth
+     * \since 6.9
+     */
+    Q_PROPERTY(qreal preferredWidth READ preferredWidth WRITE setPreferredWidth NOTIFY preferredWidthChanged)
+
+    /*!
+     * \property PlasmaQuick::ConfigModel::preferredHeight
+     * \since 6.9
+     */
+    Q_PROPERTY(qreal preferredHeight READ preferredHeight WRITE setPreferredHeight NOTIFY preferredHeightChanged)
+
 public:
     /*!
      * \value NameRole
@@ -198,12 +230,21 @@ public:
      **/
     QQmlListProperty<ConfigCategory> categories();

+    qreal preferredWidth() const;
+    void setPreferredWidth(qreal width);
+
+    qreal preferredHeight() const;
+    void setPreferredHeight(qreal height);
+
 Q_SIGNALS:
     /*!
      *
      */
     void countChanged();

+    void preferredWidthChanged();
+    void preferredHeightChanged();
+
 private:
     friend class ConfigModelPrivate;
     ConfigModelPrivate *const d;
-- 
2.53.0
